package com.tanidikvar.api.discussion.repository;import com.tanidikvar.api.discussion.dto.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;@Repository public class DiscussionRepository{private final JdbcTemplate jdbc;public DiscussionRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public Optional<UUID> questionId(UUID answer){return jdbc.query("SELECT question_id FROM answers WHERE id=?",(r,n)->r.getObject(1,UUID.class),answer).stream().findFirst();}public boolean visibleAnswer(UUID id){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM answers a JOIN questions q ON q.id=a.question_id WHERE a.id=? AND a.deleted_at IS NULL AND a.moderated_at IS NULL AND q.deleted_at IS NULL)",Boolean.class,id));}public AnswerCommentResponse add(UUID answer,UUID user,String body){UUID id=UUID.randomUUID();return jdbc.query("INSERT INTO answer_comments(id,answer_id,author_id,body) VALUES (?,?,?,?) RETURNING id,answer_id,author_id,body,created_at,version",(r,n)->new AnswerCommentResponse(r.getObject("id",UUID.class),r.getObject("answer_id",UUID.class),r.getObject("author_id",UUID.class),name(user),r.getString("body"),r.getTimestamp("created_at").toInstant(),r.getLong("version")),id,answer,user,body.trim()).getFirst();}public List<AnswerCommentResponse> list(UUID answer,int page,int size){return jdbc.query("SELECT c.*,concat(p.first_name,' ',p.last_name) author_name FROM answer_comments c JOIN user_profiles p ON p.user_id=c.author_id WHERE c.answer_id=? AND c.deleted_at IS NULL ORDER BY c.created_at,c.id LIMIT ? OFFSET ?",(r,n)->map(r),answer,size,page*size);}public Optional<AnswerCommentResponse> comment(UUID answer,UUID id){return jdbc.query("SELECT c.*,concat(p.first_name,' ',p.last_name) author_name FROM answer_comments c JOIN user_profiles p ON p.user_id=c.author_id WHERE c.answer_id=? AND c.id=? AND c.deleted_at IS NULL",(r,n)->map(r),answer,id).stream().findFirst();}private AnswerCommentResponse map(java.sql.ResultSet r)throws java.sql.SQLException{return new AnswerCommentResponse(r.getObject("id",UUID.class),r.getObject("answer_id",UUID.class),r.getObject("author_id",UUID.class),r.getString("author_name"),r.getString("body"),r.getTimestamp("created_at").toInstant(),r.getLong("version"));}public void update(UUID id,String body){jdbc.update("UPDATE answer_comments SET body=?,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=?",body.trim(),id);}public long count(UUID answer){return jdbc.queryForObject("SELECT count(*) FROM answer_comments WHERE answer_id=? AND deleted_at IS NULL",Long.class,answer);}public boolean best(UUID question,UUID answer,UUID actor){int changed=jdbc.update("UPDATE questions SET best_answer_id=?,updated_at=CURRENT_TIMESTAMP,version=version+1 WHERE id=? AND author_id=? AND archived_at IS NULL AND deleted_at IS NULL AND EXISTS(SELECT 1 FROM answers WHERE id=? AND question_id=? AND deleted_at IS NULL AND moderated_at IS NULL)",answer,question,actor,answer,question);if(changed>0){UUID owner=jdbc.queryForObject("SELECT author_id FROM answers WHERE id=?",UUID.class,answer);jdbc.update("INSERT INTO point_events(id,user_id,event_type,points,source_type,source_id,policy_version) VALUES (md5('best-answer:'||?::text)::uuid,?,'BEST_ANSWER',15,'ANSWER',?,1) ON CONFLICT DO NOTHING",answer,owner,answer);jdbc.update("INSERT INTO notifications(id,user_id,notification_type,title,body,target_type,target_id) VALUES(md5('best-answer-note:'||?::text)::uuid,?,'BEST_ANSWER','Yanıtın en iyi cevap seçildi','Soru sahibi yanıtını en iyi cevap olarak işaretledi.','ANSWER',?) ON CONFLICT DO NOTHING",answer,owner,answer);}return changed>0;}public List<QuestionTemplateResponse> templates(String category){return jdbc.query("SELECT id,category,title,body,scope_hint FROM question_templates WHERE deleted_at IS NULL AND (?='' OR category=?) ORDER BY category,title",(r,n)->new QuestionTemplateResponse(r.getObject("id",UUID.class),r.getString("category"),r.getString("title"),r.getString("body"),r.getString("scope_hint")),category,category);}private String name(UUID user){return jdbc.queryForObject("SELECT concat(first_name,' ',last_name) FROM user_profiles WHERE user_id=?",String.class,user);}}
